<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigEnabledUserEmailAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigEnabledUserEmailAccessor trait.
 *
 * Covers null default, string/VO assignment via withEnabledUserEmail,
 * getEnabledUserEmail/enabledUserEmail accessors, and isEnabledUserEmailChanged with/without original.
 */
class TenantConfigEnabledUserEmailAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withEnabledUserEmail creates a new instance with the EnabledUserEmail set
     * from a string value, and getEnabledUserEmail returns the primitive string.
     */
    public function testWithEnabledUserEmailFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnabledUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withEnabledUserEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getEnabledUserEmail());
    }
    /**
     * Asserts that withenabledUserEmail has access to the value object
     * from a string value, and getEnabledUserEmail returns the primitive string.
     */
    public function testWithEnabledUserEmailFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnabledUserEmailAccessorUnitTest();

        // Act
        $result = $holder->withEnabledUserEmail('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->enabledUserEmail()->value());
    }
    public function testChangedEnabledUserEmail(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigEnabledUserEmailAccessorUnitTest();
        $original = $holder->withEnabledUserEmail( 'one');
        $same = $holder->withEnabledUserEmail( 'one');
        $modified = $holder->withEnabledUserEmail('other');

        // Act
        $unchanged = $holder->isEnabledUserEmailChanged();
        $withSame = $original->isEnabledUserEmailChanged( $same );
        $withDiferent = $original->isEnabledUserEmailChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigEnabledUserEmailAccessorUnitTest
{
  use TenantConfigEnabledUserEmailAccessor;
}
